import React from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Home from './Home';                 // tu home actual
import ProductPage from './pages/ProductPage';
import CategoryPage from './pages/CategoryPage';
import SellerPage from './pages/SellerPage';
import AudienceGate from './pages/AudienceGate';
import HeaderNew from './components/HeaderNew';
import { getAudience } from './utils/audience';

function RequireAudience({ children }) {
  const location = useLocation();
  const aud = getAudience();        // 'RESIDENT' | 'TOURIST' | null
  if (!aud) {
    return <Navigate to="/audiencia" state={{ from: location }} replace />;
  }
  return children;
}

export default function App() {
  return (
    <div className="page">
      <HeaderNew />
      <Routes>
        {/* selector full-screen (no requiere audiencia previa) */}
        <Route path="/audiencia" element={<AudienceGate />} />

        {/* rutas protegidas por audiencia */}
        <Route
          path="/"
          element={
            <RequireAudience>
              <Home />
            </RequireAudience>
          }
        />
        <Route
          path="/producto/:id"
          element={
            <RequireAudience>
              <ProductPage />
            </RequireAudience>
          }
        />
        <Route
          path="/categoria/:id"
          element={
            <RequireAudience>
              <CategoryPage />
            </RequireAudience>
          }
        />
        <Route
          path="/negocio/:id"
          element={
            <RequireAudience>
              <SellerPage />
            </RequireAudience>
          }
        />

        {/* fallback */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </div>
  );
}
